  str_junior_skin_draw_cn16_intro_head_2 = "ศูนย์แลกเปลี่ยน",
  str_junior_skin_draw_cn16_intro_body_2 = "- สามารถใช้ Divergent Cocoons ในการแลกเปลี่ยนที่ Exchange Center เพื่อรับชุด Divergence - Chen'ni <color=#063c8e>\"สันติภาพและความสามัคคี\"</color>, กรอบอวตาร Divergence พิเศษ, อวตาร Divergence, Special Star Flare, Star Flare และรางวัลอื่น ๆ \n- สะสม Divergent Cocoons ×<color=#d70500>198</color> เพื่อแลกรับชุด Divergence - Chen'ni <color=#063c8e>\"สันติภาพและความสามัคคี\"</color> (เพียงครั้งเดียว) หากคุณมีชุดนี้อยู่แล้ว คุณจะได้รับ Divergent Cocoon ×<color=#d70500>100</color> แทน.",
  str_junior_skin_draw_cn16_intro_head_3 = "อีเวนต์สิ้นสุดแล้ว",
  str_junior_skin_draw_cn16_intro_body_3 = "○ หลังจากอีเวนต์สิ้นสุด พลังแยกทางที่ไม่ได้ใช้จะถูกแปลงเป็นลูมแอมเบอร์ในอัตรา <color=#d70500>1:40</color> และดักแด้แยกทางที่ไม่ได้ใช้จะถูกแปลงเป็นไนท์เทียมในอัตรา <color=#d70500>1:3,000</color> รางวัลที่แปลงแล้วจะถูกส่งผ่านทางจดหมายในเกมหลังจากอีเวนต์สิ้นสุด",
  str_junior_skin_draw_cn16_probability_title = "ข้อมูลความน่าจะเป็นของกิจกรรมความสงบสุข: ความแตกต่าง",
  str_junior_skin_draw_cn16_probability_head = "กติกาอีเวนต์",
  str_junior_skin_draw_cn16_probability_body = "ในกิจกรรมนี้ มีโอกาสที่จะได้รับรางวัลแบบสุ่มต่อไปนี้ทุกครั้งที่คุณใช้เวทมนตร์ มันเป็นไปได้ที่จะได้รางวัลเดียวกันมากกว่าหนึ่งครั้ง โอกาสทั้งหมดในการได้รับรางวัลทั้งหมดเท่ากับ 1 เสมอ",
  str_junior_skin_draw_cn16_probability_txt1 = "ในช่วงอีเวนต์นี้ มีโอกาสคงที่ที่จะได้รับรางวัลสุ่มต่อไปนี้ทุกครั้งที่คุณใช้เทพเจ้า:",
