  str_junior_skin_draw_n47_7000512_name = "ผดุงไว้ซึ่งศักดิ์ศรี",
  str_junior_skin_draw_n47_7000512_desc = "ชุดสูทที่ตัดเย็บเป็นพิเศษนั้นเหมือนมอนสเตอร์—มันกลืนคนที่เต็มไปด้วยความขี้ขลาด ความกลัวเวที หรือความไม่มั่นใจ แต่มันถอนรูปให้กับไรน์ฮาร์ต โดยเน้นเฉพาะการโชว์ความแข็งแกร่งและความมั่นคงของเธอ\nการตัดเย็บที่ดีเหมาะกับรูปร่างของเธออย่างสมบูรณ์ โดดเด่นทุกส่วนที่เธอฝึกฝนอย่างดี การออกแบบที่เรียบหรูไม่เคยล้าสมัย แตกต่างด้วยความคมคายบนเธอเพราะเธอคือคนที่จะนำยุคนี้ไปสู่อนาคตชุดที่เธอสวมใส่คืนนี้คือเกราะป้องกันในการต่อสู้ และแก้วไวน์คือหอกของเธอ มีอาวุธคมคาย และเธอก้าวเข้าสู่งานเลี้ยงในฐานะจอมทัพแห่งอิลลูมินา นักการทูตที่มีวิสัยทัศน์เพื่ออนาคต",
